let owner=null,panel=null;
export function createMoonActions(getSimulation,{interior}={}){const token={};function show(){if(!panel){const style=document.createElement('style');style.textContent='.moon-actions{position:fixed;bottom:88px;left:50%;transform:translateX(-50%);z-index:15;display:flex;align-items:center;gap:8px;max-width:calc(100vw - 24px);font:12px Manrope,sans-serif}.moon-actions button,.moon-actions output{border:1px solid #ffffff66;border-radius:99px;padding:9px 13px;background:#10232b66;color:#fff;backdrop-filter:blur(8px);white-space:nowrap}.moon-actions button{cursor:pointer}.moon-actions button:disabled{opacity:.65;cursor:default}.moon-actions output{font-size:11px}body:not([data-family="moon"]) .moon-actions{display:none}@media(max-width:600px){.moon-actions{bottom:84px;gap:5px}.moon-actions button{padding:8px 10px;font-size:11px}.moon-actions output{display:none}}';document.head.append(style);panel=document.createElement('div');panel.className='moon-actions';panel.setAttribute('aria-label','Moon scene actions');panel.innerHTML='<button type="button">Request dropship</button><button type="button" data-action="interior" hidden>Show interior</button><output aria-live="polite"></output>';document.body.append(panel);}owner=token;const sim=getSimulation(),a=sim.dispatchAvailability();const button=panel.querySelector('button');button.textContent=a.ready?'↓ Request dropship':a.label;button.disabled=!a.ready;button.title='One extra supply drop per month. Arrives in 16 simulation seconds; supplies are recorded as Earth imports.';button.onclick=()=>{getSimulation().requestDropship();show();};const cabinButton=panel.querySelector('[data-action=interior]');cabinButton.hidden=!interior?.interiorAvailable;cabinButton.disabled=!interior?.interiorDocked;cabinButton.textContent=interior?.interiorOpen?'Close hull':'Show interior';cabinButton.setAttribute('aria-pressed',String(!!interior?.interiorOpen));cabinButton.title=interior?.interiorDocked?'Inspect the fitted cabin: 6 seats, 2 berths, galley and washroom.':'Interior inspection is available while docked.';cabinButton.onclick=()=>{interior.setInterior(!interior.interiorOpen);show();};panel.querySelector('output').textContent=sim.state.rocket.dispatch?'Dispatch in progress':`${sim.state.rocket.extraVisits||0} requested drops delivered`;}
 return {update:show,dispose(){if(owner===token){panel?.remove();panel=null;owner=null;}}};}
